// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.bulk;

import java.util.Locale;
import java.util.Objects;

/**
 * Selects the codec used for the bulk loader's intermediate files: the staged inputs, the external sorter runs and the
 * spool files that a load writes to the workspace directory and reads back before publishing the store.
 * <p>
 * The loader normally uses two LZ4 codecs: the fast compressor for the write-once run and spool files on the hot path,
 * and the high-ratio compressor at level 9 for the long-lived staged inputs that are re-read several times and
 * therefore warrant spending extra CPU to shrink on disk. {@link #FASTEST} keeps exactly that split. An explicit
 * {@linkplain #level(int) level} overrides <em>both</em> tiers, and {@link #NONE} writes every intermediate file
 * uncompressed, trading disk for CPU.
 * <p>
 * Compressed files remain readable regardless of the level they were written at, so changing between {@code FASTEST}
 * and any level is safe. Switching to or from {@link #NONE} is not, which is why a resumed load keeps whatever setting
 * its workspace was created with.
 */
public record BulkCompression(Kind kind, int level) {

	/**
	 * Lowest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MINIMUM_LEVEL = 1;

	/**
	 * Highest level accepted by {@code LZ4Factory.highCompressor(int)}.
	 */
	public static final int MAXIMUM_LEVEL = 17;

	/**
	 * Level the loader applies to staged inputs under {@link #FASTEST}.
	 */
	static final int STAGED_INPUT_LEVEL = 9;

	private static final String FASTEST_TOKEN = "fastest";
	private static final String NONE_TOKEN = "none";

	/**
	 * The default: LZ4's fast compressor for run and spool files, and its high-ratio compressor at level 9 for staged
	 * inputs.
	 */
	public static final BulkCompression FASTEST = new BulkCompression(Kind.FASTEST, 0);

	/**
	 * No compression; every intermediate file is written as raw bytes.
	 */
	public static final BulkCompression NONE = new BulkCompression(Kind.NONE, 0);

	public BulkCompression {
		Objects.requireNonNull(kind, "kind");
		if (kind == Kind.HIGH) {
			requireValidLevel(level);
		} else if (level != 0) {
			throw new IllegalArgumentException(kind + " does not carry a compression level");
		}
	}

	/**
	 * Applies LZ4's high-ratio compressor at {@code level} to every intermediate file.
	 *
	 * @param level a compression level between {@value #MINIMUM_LEVEL} and {@value #MAXIMUM_LEVEL}
	 */
	public static BulkCompression level(int level) {
		return new BulkCompression(Kind.HIGH, level);
	}

	/**
	 * Parses {@code fastest}, {@code none} or a compression level. Surrounding whitespace and letter case are ignored.
	 *
	 * @throws IllegalArgumentException if the token is neither a known name nor a level in range
	 */
	public static BulkCompression parse(String token) {
		String normalized = Objects.requireNonNull(token, "token").trim().toLowerCase(Locale.ROOT);
		if (FASTEST_TOKEN.equals(normalized)) {
			return FASTEST;
		}
		if (NONE_TOKEN.equals(normalized)) {
			return NONE;
		}
		int parsed;
		try {
			parsed = Integer.parseInt(normalized);
		} catch (NumberFormatException e) {
			throw new IllegalArgumentException(
					"Compression must be " + FASTEST_TOKEN + ", " + NONE_TOKEN + ", or a level between "
							+ MINIMUM_LEVEL + " and " + MAXIMUM_LEVEL + ", but was: " + token);
		}
		return level(parsed);
	}

	/**
	 * The stable text form of this selection, as accepted by {@link #parse(String)}. Used for the command line and for
	 * the workspace manifest.
	 */
	public String token() {
		return switch (kind) {
		case FASTEST -> FASTEST_TOKEN;
		case NONE -> NONE_TOKEN;
		case HIGH -> Integer.toString(level);
		};
	}

	private static void requireValidLevel(int level) {
		// LZ4Factory.highCompressor(int) silently clamps out-of-range levels, so validate before it can hide a typo.
		if (level < MINIMUM_LEVEL || level > MAXIMUM_LEVEL) {
			throw new IllegalArgumentException(
					"Compression level must be between " + MINIMUM_LEVEL + " and " + MAXIMUM_LEVEL + ", but was: "
							+ level);
		}
	}

	@Override
	public String toString() {
		return token();
	}

	public enum Kind {
		/** LZ4 fast compressor on the hot path, LZ4 high-ratio level 9 for staged inputs. */
		FASTEST,
		/** No compression at all. */
		NONE,
		/** LZ4 high-ratio compressor at an explicit level, everywhere. */
		HIGH
	}
}
